		l := strings.Split(s, "\n")
		sort.Strings(l)
		return strings.Join(l, "|")
	}

	for i := 0; i < 6000; i++ {
		density := []int{15, 40, 70, 95}[i%4]
		var desc []string
		for _, v := range vars {
			_ = os.Unsetenv(v)
			_ = os.Unsetenv(v + "_FILE")
			if r.Intn(100) < density {
				val := pool[r.Intn(len(pool))]
				_ = os.Setenv(v, val)
				desc = append(desc, fmt.Sprintf("%s=%q", v, val))
			}
		}
		var buf bytes.Buffer
		logger = log.New(&buf, "", 0)
		displayStartupConfig()
		fmt.Fprintf(&out, "CASE %d %s\nDISPLAY:\n%s", i, strings.Join(desc, " "), buf.String())
		buf.Reset()
		err := checkProvidersDefined()
		if err != nil {
			fmt.Fprintf(&out, "CPD err: %s\n", sortLines(err.Error()))
		} else {
			fmt.Fprintf(&out, "CPD ok\n")
		}
		fmt.Fprintf(&out, "CPD log: %q\n", sortLines(buf.String()))
		for _, p := range providers {
			buf.Reset()
			n, perr := checkProvider(p)
			es := ""
			if perr != nil {
				es = perr.Error()
			}
			fmt.Fprintf(&out, "CP %s n=%d err=%q log=%q\n", p, n, es, buf.String())
		}
	}
	if err := os.WriteFile(os.Getenv("ZZ_OUT"), out.Bytes(), 0o600); err != nil {
		t.Fatal(err)
	}
}
EOF
