126		bbEmail, emailExists := GetEnvOrFile(envBitBucketEmail)
127		bbToken, tokenExists := GetEnvOrFile(envBitBucketAPIToken)
128	
129		return emailExists && bbEmail != "" && tokenExists && bbToken != ""
130	}
